		callbackOptions,
		// The redirect URI of a server-specific Client ID Metadata Document.
		cimd ? [`${CALLBACK_PATH}/${callbackId(serverUrl)}`] : [],
		preferredPort,
		callbackOptions.port !== undefined,
	);
